const subs = $input.first().json.value || [];
const callRecordSubs = subs.filter(s => s.resource === 'communications/callRecords');
if (callRecordSubs.length === 0) return [{ json: { noSubsToDelete: true } }];
return callRecordSubs.map(s => ({ json: { subscriptionId: s.id } }));

// Stop if it's just a validation handshake
if ($input.first().json.query?.validationToken) return [];

const notification = $input.first().json.body?.value?.[0];
if (!notification) return [];

// Only process callRecords notifications
if (!notification.resource?.startsWith('communications/callRecords')) return [];

const callId = notification.resourceData?.id || notification.resource?.split('/').pop();

// Dedup using static data
const staticData = $getWorkflowStaticData('global');
if (!staticData.processedIds) staticData.processedIds = [];

// Remove the Test call ID so it can be reprocessed
staticData.processedIds = staticData.processedIds.filter(id => id !== callId);

// Now check and add
if (staticData.processedIds.includes(callId)) return [];
staticData.processedIds.push(callId);
if (staticData.processedIds.length > 100) {
  staticData.processedIds = staticData.processedIds.slice(-100);
}

return [{ json: { callId, clientState: notification.clientState } }];

const callRecord = $('Get Call Record').first().json;
const organizer = $('Get Organizer Profile').first().json;
const orgEmail = (organizer.mail || organizer.userPrincipalName || '').toLowerCase();
const orgName = organizer.displayName || '';
const orgUserId = callRecord.organizer?.user?.id || '';

const salesList = $input.first().json.salesEmails.split(',').map(e => e.trim().toLowerCase());
const isSales = salesList.some(e => orgEmail.includes(e));
const targetFolder = isSales ? 'Sales' : 'Operations';

// Extract attendee DISPLAY NAMES from participants (skip organizer and bots)
const participants = callRecord.participants || [];
const attendeeNames = [];
for (const p of participants) {
  const name = p.user?.displayName || p.guest?.displayName || '';
  if (!name || name === 'Guest user' || name === orgName) continue;
  if (salesList.some(e => name.toLowerCase().includes(e.split('@')[0]))) continue;
  attendeeNames.push(name);
}

const token = $('Get Token A').first().json.access_token;
const recordingsUser = $input.first().json.recordingsUser || 'team@company.com';

return [{
  json: {
    ...($input.first().json),
    isSales,
    targetFolder,
    orgEmail,
    orgName,
    orgUserId,
    recordingsUser,
    attendeeNames,
    callStart: callRecord.startDateTime,
    callEnd: callRecord.endDateTime,
    joinWebUrl: callRecord.joinWebUrl || '',
    token
  }
}];

const ctx = $('Extract Meeting Info').first().json;
const items = $input.first().json.value || [];
const subject = (ctx.meetingSubject || '').toLowerCase();

const files = items.filter(item => {
  if (!item.file) return false;
  const name = (item.name || '').toLowerCase();
  // Match full subject against filename (before the date stamp)
  if (subject && name.includes(subject)) return true;
  return false;
});

if (files.length === 0) return [];

return files.map(f => ({
  json: {
    ...ctx,
    fileId: f.id,
    fileName: f.name,
    fileSize: f.size,
    fileCreated: f.createdDateTime,
    fileOwnerEmail: ctx.orgEmail || ctx.recordingsUser || 'team@company.com'
  }
}));

const spDriveId = $('Get SharePoint Drive').first().json.id;
const items = $input.all();

return items.map(item => {
  const d = item.json;
  return {
    json: {
      ...d,
      copyBody: {
        parentReference: {
          driveId: spDriveId,
          path: '/root:/Meetings Recordings/' + d.targetFolder
        },
        "@microsoft.graph.conflictBehavior": "replace",
        name: d.fileName
      }
    }
  };
});

const items = $input.all();

return items.map(item => {
  const d = item.json;
  const monitorUrl = d.headers?.location || d.headers?.Location;
  const fileId = $('Prepare Copy').first().json.fileId;
  const token = $('Prepare Copy').first().json.token;
  const fileOwnerEmail = $('Prepare Copy').first().json.fileOwnerEmail;

  if (!monitorUrl) {
    throw new Error('Copy returned no monitor URL. Headers: ' + JSON.stringify(d.headers || {}).substring(0, 200));
  }

  return { json: { monitorUrl, fileId, token, fileOwnerEmail } };
});

