const meetingInfo = $('Extract Meeting Info').first().json;
const classify = $('Classify Call').first().json;
const emails = $('Extract Attendee Emails').first().json;
const summary = $('Parse Summary').first().json;

// Calculate duration
let duration = '';
if (classify.callStart && classify.callEnd) {
  const start = new Date(classify.callStart);
  const end = new Date(classify.callEnd);
  const diffMs = end - start;
  const diffMin = Math.round(diffMs / 60000);
  duration = diffMin + ' min';
}

// Build attendee string
const attendeeNames = (classify.attendeeNames || []).join(', ') || 'Unknown';

// Get date (just the date part)
const callDate = classify.callStart ? classify.callStart.split('T')[0] : new Date().toISOString().split('T')[0];

// Build summary text (max 2000 chars for Notion rich_text)
let summaryText = summary.slackSummary || summary.note || '';
if (summaryText.length > 2000) {
  summaryText = summaryText.substring(0, 1997) + '...';
}

// Build recording link from SharePoint info
const recordingLink = meetingInfo.recordingUrl || '';

const notionBody = {
  parent: { database_id: "32f2b80dedad804ca94dc95f5545abe9" },
  properties: {
    "Meeting Title": {
      title: [{ text: { content: meetingInfo.meetingSubject || 'Untitled Meeting' } }]
    },
    "Date": {
      date: { start: callDate }
    },
    "Attendees": {
      rich_text: [{ text: { content: attendeeNames } }]
    },
    "Duration": {
      rich_text: [{ text: { content: duration } }]
    },
    "Recording Link": {
      url: recordingLink || null
    },
    "Summary": {
      rich_text: [{ text: { content: summaryText } }]
    }
  }
};

return [{
  json: {
    ...summary,
    notionBody
  }
}];

