const raw = $input.first().json.data || $input.first().json.body || '';
const ctx = $('Classify Call').first().json;

// Parse VTT format: extract speaker and text lines
const lines = raw.split('\n');
const entries = [];
let currentSpeaker = '';
let currentText = '';

for (const line of lines) {
  const trimmed = line.trim();

  // Skip WEBVTT header and empty lines
  if (!trimmed || trimmed === 'WEBVTT' || trimmed.startsWith('NOTE')) continue;

  // Skip timestamp lines (00:00:00.000 --> 00:00:05.000)
  if (trimmed.includes('-->')) continue;

  // Speaker line: <v Speaker Name>text</v>
  const speakerMatch = trimmed.match(/<v\s+([^>]+)>(.+?)(?:<\/v>)?$/);
  if (speakerMatch) {
    const speaker = speakerMatch[1].trim();
    const text = speakerMatch[2].replace(/<\/v>/, '').trim();
    if (speaker !== currentSpeaker) {
      if (currentText) entries.push({ speaker: currentSpeaker, text: currentText });
      currentSpeaker = speaker;
      currentText = text;
    } else {
      currentText += ' ' + text;
    }
  } else if (trimmed && !trimmed.match(/^\d+$/) && !trimmed.match(/^\d{2}:/)) {
    // Plain text line (continuation)
    if (currentText) currentText += ' ' + trimmed;
  }
}
if (currentText) entries.push({ speaker: currentSpeaker, text: currentText });

// Format as readable transcript
const transcript = entries.map(e => e.speaker + ': ' + e.text).join('\n\n');

if (!transcript || transcript.length < 50) {
  // Fallback: just clean the raw text
  const fallback = raw.replace(/<[^>]+>/g, '').replace(/WEBVTT[\s\S]*?\n\n/, '').replace(/\d{2}:\d{2}:\d{2}\.\d{3}\s*-->\s*\d{2}:\d{2}:\d{2}\.\d{3}/g, '').replace(/^\d+$/gm, '').trim();
  return [{ json: { ...ctx, transcript: fallback || 'Transcript could not be parsed' } }];
}

return [{ json: { ...ctx, transcript } }];

const items = $input.first().json.value || [];
const ctx = $('Classify Call').first().json;

const recFolder = items.find(i => i.folder && i.name === 'Recordings');
if (!recFolder) return [];

return [{ json: { ...ctx, recordingsFolderId: recFolder.id } }];

const ctx = $('Classify Call').first().json;
const calData = $input.first().json;
const events = calData.value || [];

// Find matching event by subject
const meetingSubject = ctx.joinWebUrl ? '' : ''; // we don't have subject yet
const salesList = ctx.salesEmails.split(',').map(e => e.trim().toLowerCase());

// Collect external attendee emails from calendar event
const attendeeEmails = [];
let domain = '';

for (const ev of events) {
  const attendees = ev.attendees || [];
  for (const a of attendees) {
    const email = (a.emailAddress?.address || '').toLowerCase();
    const name = a.emailAddress?.name || '';
    if (!email) continue;
    // Skip internal (sales) emails
    if (salesList.some(s => email.includes(s))) continue;
    // Skip yourcompany.com domain entirely
    if (email.endsWith('@yourcompany.com')) continue;
    attendeeEmails.push({ email, name });
    // Extract domain from first external email
    if (!domain && email.includes('@')) {
      domain = email.split('@')[1];
    }
  }
}

return [{
  json: {
    ...ctx,
    attendeeEmails,
    externalDomain: domain,
    attendeeNames: attendeeEmails.map(a => a.name).concat(ctx.attendeeNames || []).filter((v, i, arr) => arr.indexOf(v) === i)
  }
}];

const results = $input.first().json.results || [];
const RENEWAL_PIPELINE = '820213778';

// Closed stage IDs (deals we consider "closed")
const closedStages = ['266058584', '266058587', '266058586', '266058588', // Sales closed
  '1211728151', '1211728153', // Renewal closed
  '1297403657', // CAP closed
  '1127106359', '1127121742' // No response
];

// Separate deals into categories
const openNonRenewal = [];
const renewal = [];
const other = [];

for (const deal of results) {
  const pipeline = deal.properties?.pipeline || '';
  const stage = deal.properties?.dealstage || '';
  const isClosed = closedStages.includes(stage);

  if (pipeline === RENEWAL_PIPELINE) {
    renewal.push(deal);
  } else if (!isClosed) {
    openNonRenewal.push(deal);
  } else {
    other.push(deal);
  }
}

// Pick: first open non-renewal, then renewal, then most recent anything
const picked = openNonRenewal[0] || renewal[0] || other[0] || results[0];

if (!picked) return [];

return [{
  json: {
    ...($('Extract Attendee Emails').first().json),
    deal: picked,
    dealId: picked.id,
    dealName: picked.properties?.dealname || '',
    dealProperties: picked.properties || {}
  }
}];

const ctx = $('Extract Attendee Emails').first().json;
const whisperText = $input.first().json.text || '';

